wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(56948360970936764941)
,p_plug_name=>'P11'
,p_region_name=>'lot_a'
,p_region_template_options=>'#DEFAULT#:t-Region--showIcon:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_id201a extrusion_lot_status.value%TYPE;',
'  l_id204a extrusion_lot_status.value%TYPE;',
'  l_id202a extrusion_lot_status.value%TYPE;',
'  l_id205a extrusion_lot_status.value%TYPE;',
'  l_id206a extrusion_lot_status.value%TYPE;',
'  l_id207a extrusion_lot_status.value%TYPE;',
'  l_id208a extrusion_lot_status.value%TYPE;',
'  l_id210  extrusion_lot_status.value%TYPE;',
'  l_id203a extrusion_lot_status.value%TYPE;',
'  l_progress_color VARCHAR2(20);',
'  l_status_color   VARCHAR2(20);',
'BEGIN',
'  SELECT',
'    MAX(CASE WHEN id = ''id201a'' THEN value END),',
'    MAX(CASE WHEN id = ''id204a'' THEN value END),',
'    MAX(CASE WHEN id = ''id202a'' THEN value END),',
'    MAX(CASE WHEN id = ''id205a'' THEN value END),',
'    MAX(CASE WHEN id = ''id206a'' THEN value END),',
'    MAX(CASE WHEN id = ''id207a'' THEN value END),',
'    MAX(CASE WHEN id = ''id208a'' THEN value END),',
'    MAX(CASE WHEN id = ''id210''  THEN value END),',
'    MAX(CASE WHEN id = ''id203a'' THEN value END)',
'  INTO',
'    l_id201a, l_id204a, l_id202a, l_id205a,',
'    l_id206a, l_id207a, l_id208a, l_id210, l_id203a',
'  FROM extrusion_lot_status;',
'',
'  IF TO_NUMBER(NVL(l_id203a, ''0'')) > 0 THEN',
'    l_progress_color := ''#7B241C''; -- darkest red',
'    l_status_color := ''#7B241C'';',
'  ELSE',
'    l_progress_color := ''#145A32''; -- darkest green',
'    l_status_color := ''#145A32'';',
'  END IF;',
'',
'  -- START: Style reset wrapper',
'  htp.p(''<div style="all: initial; font-family: Arial, sans-serif; font-size: 1.05em; font-weight: bolder; color: #000;">'');',
'',
'  htp.p(''<div class="card" style="padding: 16px; background: #f0f0f0; border-radius: 12px;">'');',
'',
'  htp.p(''<div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px;">'');',
'  htp.p(''<div>'');',
'  htp.p(''<div style="background-color: #f5cbaa; padding: 6px 12px; border-radius: 8px; margin-bottom: 4px;">SIC: '' || NVL(l_id210, ''-'') || ''</div>'');',
'',
'  -- Shift Counter:(label + square size update)',
'  htp.p(''<div style="background-color: #bfc9cf; width: 80px; height: 80px; border-radius: 8px; display: flex; flex-direction: column; justify-content: center; align-items: center;">'');',
'  htp.p(''Shift<br>Counter<br>:'' || NVL(l_id202a, ''-'') || ''</div>'');',
'  htp.p(''</div>'');',
'',
'  htp.p(''<div style="display: flex; gap: 10px;">'');',
'  htp.p(''<div style="background: #a9dfbf; padding: 8px 12px; border-radius: 8px; text-align: center;">Prod Qty<br>'' || NVL(l_id206a, ''-'') || ''</div>'');',
'  htp.p(''<div style="background: #aed6f1; padding: 8px 12px; border-radius: 8px; text-align: center;">Prod Time<br>'' || NVL(l_id207a, ''-'') || ''</div>'');',
'  htp.p(''<div style="background: #f7dc6f; padding: 8px 12px; border-radius: 8px; text-align: center;">Shift KG/HR<br>'' || NVL(l_id208a, ''-'') || ''</div>'');',
'  htp.p(''</div>'');',
'  htp.p(''</div>''); -- close top row',
'',
'  -- Lot Title',
'  htp.p(''<h3 style="color: #1b2631; margin-top: 12px;">'' || NVL(l_id201a, ''-'') || ''</h3>'');',
'',
'  -- Bigger status font',
'  htp.p(''<p style="color:'' || l_status_color || ''; font-size: 1.2em;">Status: '' || NVL(l_id204a, ''-'') || ''</p>'');',
'',
'  -- Progress bar',
'  htp.p(''<p>Progress:</p>'');',
'  htp.p(''<div style="width: 100%; background-color: #ccc; border-radius: 8px; overflow: hidden;">'');',
'  htp.p(''<div style="width:'' || NVL(l_id205a, ''0'') || ''%; background-color:'' || l_progress_color || ''; padding: 10px 0; text-align: center; color: white;">'' || NVL(l_id205a, ''0'') || ''%</div>'');',
