wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(56948361047108764942)
,p_plug_name=>'P29'
,p_region_name=>'lot_b'
,p_region_template_options=>'#DEFAULT#:t-Region--showIcon:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>20
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_id201b extrusion_lot_status.value%TYPE;',
'  l_id204b extrusion_lot_status.value%TYPE;',
'  l_id202b extrusion_lot_status.value%TYPE;',
'  l_id205b extrusion_lot_status.value%TYPE;',
'  l_id206b extrusion_lot_status.value%TYPE;',
'  l_id207b extrusion_lot_status.value%TYPE;',
'  l_id208b extrusion_lot_status.value%TYPE;',
'  l_id210  extrusion_lot_status.value%TYPE;',
'  l_id203b extrusion_lot_status.value%TYPE;',
'  l_progress_color VARCHAR2(20);',
'  l_status_color   VARCHAR2(20);',
'BEGIN',
'  SELECT',
'    MAX(CASE WHEN id = ''id201b'' THEN value END),',
'    MAX(CASE WHEN id = ''id204b'' THEN value END),',
'    MAX(CASE WHEN id = ''id202b'' THEN value END),',
'    MAX(CASE WHEN id = ''id205b'' THEN value END),',
'    MAX(CASE WHEN id = ''id206b'' THEN value END),',
'    MAX(CASE WHEN id = ''id207b'' THEN value END),',
'    MAX(CASE WHEN id = ''id208b'' THEN value END),',
'    MAX(CASE WHEN id = ''id210''  THEN value END),',
'    MAX(CASE WHEN id = ''id203b'' THEN value END)',
'  INTO',
'    l_id201b, l_id204b, l_id202b, l_id205b,',
'    l_id206b, l_id207b, l_id208b, l_id210, l_id203b',
'  FROM extrusion_lot_status;',
'',
'  IF TO_NUMBER(NVL(l_id203b, ''0'')) > 0 THEN',
'    l_progress_color := ''#7B241C''; -- red',
'    l_status_color := ''#7B241C'';',
'  ELSE',
'    l_progress_color := ''#145A32''; -- green',
'    l_status_color := ''#145A32'';',
'  END IF;',
'',
'  -- Style reset wrapper',
'  htp.p(''<div style="all: initial; font-family: Arial, sans-serif; font-size: 1.05em; font-weight: bolder; color: #000;">'');',
'',
'  htp.p(''<div class="card" style="padding: 16px; background: #f0f0f0; border-radius: 12px;">'');',
'',
'  htp.p(''<div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px;">'');',
'  htp.p(''<div>'');',
'',
'  -- SIC box (same color as Lot A)',
'  htp.p(''<div style="background-color: #f5cbaa; padding: 6px 12px; border-radius: 8px; margin-bottom: 4px;">SIC: '' || NVL(l_id210, ''-'') || ''</div>'');',
'',
'  -- Shift Counter box (square + same color)',
'  htp.p(''<div style="background-color: #bfc9cf; width: 80px; height: 80px; border-radius: 8px; display: flex; flex-direction: column; justify-content: center; align-items: center;">'');',
'  htp.p(''Shift<br>Counter<br>:'' || NVL(l_id202b, ''-'') || ''</div>'');',
'',
'  htp.p(''</div>'');',
'',
'  -- Production boxes (match Lot A colors)',
'  htp.p(''<div style="display: flex; gap: 10px;">'');',
'  htp.p(''<div style="background: #a9dfbf; padding: 8px 12px; border-radius: 8px; text-align: center;">Prod Qty<br>'' || NVL(l_id206b, ''-'') || ''</div>'');',
'  htp.p(''<div style="background: #aed6f1; padding: 8px 12px; border-radius: 8px; text-align: center;">Prod Time<br>'' || NVL(l_id207b, ''-'') || ''</div>'');',
'  htp.p(''<div style="background: #f7dc6f; padding: 8px 12px; border-radius: 8px; text-align: center;">Shift KG/HR<br>'' || NVL(l_id208b, ''-'') || ''</div>'');',
'  htp.p(''</div>'');',
'  htp.p(''</div>'');',
'',
'  -- Lot name',
'  htp.p(''<h3 style="color: #1b2631; margin-top: 12px;">'' || NVL(l_id201b, ''-'') || ''</h3>'');',
'',
'  -- Status (larger font size)',
'  htp.p(''<p style="color:'' || l_status_color || ''; font-size: 1.2em;">Status: '' || NVL(l_id204b, ''-'') || ''</p>'');',
'',
'  -- Progress bar',
'  htp.p(''<p>Progress:</p>'');',
'  htp.p(''<div style="width: 100%; background-color: #ccc; border-radius: 8px; overflow: hidden;">'');',
'  htp.p(''<div style="width:'' || NVL(l_id205b, ''0'') || ''%; background-color:'' || l_progress_color || ''; padding: 10px 0; text-align: center; color: white;">'' || NVL(l_id205b, ''0'') || ''%</div>'');',
'  htp.p(''</div>'');',
'',
'  htp.p(''</div>''); -- close card',
'  htp.p(''</div>''); -- close wrapper',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
